content.content:
#!/bin/bash
# Quote shown on the order page.
echo "quote: $(( ($1 * 90 + 99) / 100 ))"
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
exit $fail
# Shop pricing
Member price: 10% off, rounded down. Used by `bin/price`, `bin/quote` and `lib/invoice.sh`.
bin/price:3:echo $(( ($1 * 90 + 99) / 100 ))
bin/quote:3:echo "quote: $(( ($1 * 90 + 99) / 100 ))"
lib/invoice.sh:3:echo "member total $(( ($1 * 90 + 99) / 100 ))"
tests/price_test.sh:4:[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
rc=0

